export function getImageUrl(id: string): string | null {
  const prefix = 'https://testingcf.jsdelivr.net/gh/lolo-desu/lolocard/src/日记络络/图片' as const;
  if (characters.includes(id)) {
    return `${prefix}/立绘/${id}`;
  }
  if (backgrounds.includes(id)) {
    return `${prefix}/背景/${id}`;
  }
  return null;
}
